import {crc32,concat,bytes} from './engine.js';
function le(n,size=4){const b=new Uint8Array(size),v=new DataView(b.buffer);if(size===2)v.setUint16(0,n,true);else v.setUint32(0,n,true);return b;}
export function zip(files){let offset=0,total=0;const locals=[],central=[];if(files.length>60000)throw new Error('输出文件数量过多');for(const f of files){const name=bytes(f.name),data=f.data;total+=data.length;if(total>256*1024*1024)throw new Error('输出超过 256 MB，请分批处理');const crc=crc32(data),head=concat([le(0x04034b50),le(20,2),le(0x800,2),le(0,2),le(0,2),le(33,2),le(crc),le(data.length),le(data.length),le(name.length,2),le(0,2),name]);locals.push(head,data);central.push(concat([le(0x02014b50),le(20,2),le(20,2),le(0x800,2),le(0,2),le(0,2),le(33,2),le(crc),le(data.length),le(data.length),le(name.length,2),le(0,2),le(0,2),le(0,2),le(0,2),le(0),le(offset),name]));offset+=head.length+data.length;}const c=concat(central);return concat([...locals,c,le(0x06054b50),le(0,2),le(0,2),le(files.length,2),le(files.length,2),le(c.length),le(offset),le(0,2)]);}
